SELECT sum(n) AS total
FROM read_csv(
  'printf "n\n1\n2\n3\n" |',
  header = true
);
-- 6

COPY (SELECT range AS n FROM range(1, 4))
TO '| gzip > /tmp/qf-shellfs.csv.gz'
(FORMAT CSV, HEADER, COMPRESSION UNCOMPRESSED);

SELECT sum(n) AS total
FROM read_csv('/tmp/qf-shellfs.csv.gz');
-- 6
